const fs = require('fs');

function solve() {
    const input = fs.readFileSync(0, 'utf-8');
    let pos = 0;

    // Função rápida para pular espaços em branco e ler inteiros
    function nextInt() {
        while (pos < input.length && input.charCodeAt(pos) <= 32) {
            pos++;
        }
        if (pos >= input.length) return null;
        let res = 0;
        while (pos < input.length && input.charCodeAt(pos) > 32) {
            res = res * 10 + (input.charCodeAt(pos) - 48);
            pos++;
        }
        return res;
    }

    const n = nextInt();
    const f = nextInt();
    if (n === null) return;

    // Ler as N strings da matriz
    const grid = [];
    for (let i = 0; i < n; i++) {
        while (pos < input.length && input.charCodeAt(pos) <= 32) {
            pos++;
        }
        let start = pos;
        while (pos < input.length && input.charCodeAt(pos) > 32) {
            pos++;
        }
        grid.push(input.slice(start, pos).split(''));
    }

    // Se o ponto de início (0,0) tiver altitude maior que a força F, nada é invadido
    if (Number(grid[0][0]) <= f) {
        // BFS
        const totalCells = n * n;
        const queueR = new Int16Array(totalCells);
        const queueC = new Int16Array(totalCells);
        let head = 0;
        let tail = 0;

        queueR[tail] = 0;
        queueC[tail] = 0;
        tail++;
        grid[0][0] = '*';

        const dr = [-1, 1, 0, 0];
        const dc = [0, 0, -1, 1];

        while (head < tail) {
            const r = queueR[head];
            const c = queueC[head];
            head++;

            for (let i = 0; i < 4; i++) {
                const nr = r + dr[i];
                const nc = c + dc[i];

                if (nr >= 0 && nr < n && nc >= 0 && nc < n) {
                    const char = grid[nr][nc];
                    if (char !== '*') {
                        if (char.charCodeAt(0) - 48 <= f) {
                            grid[nr][nc] = '*';
                            queueR[tail] = nr;
                            queueC[tail] = nc;
                            tail++;
                        }
                    }
                }
            }
        }
    }

    // Gerar saída
    let out = '';
    for (let i = 0; i < n; i++) {
        out += grid[i].join('') + '\n';
    }
    process.stdout.write(out);
}

solve();
